"""Intrinsic body continuation must not be suppressed as neighbouring ruby."""
from pathlib import Path
import subprocess
root=Path(__file__).resolve().parents[2]
translation=root/'Aidoku/Core/Translation'
cache=root/'build/inline-body-ruby-smoke';cache.mkdir(exist_ok=True,parents=True)
main='\nimport Foundation\nimport CoreGraphics\nvar checks=0\nfunc check(_ value:Bool,_ message:String) {if !value {fatalError(message)};checks+=1}\nfor scale:CGFloat in [0.5,1,2] {for degrees in stride(from:0.0,to:360,by:15) {\n let t=CGAffineTransform(scaleX:scale,y:scale).rotated(by:CGFloat(degrees)*CGFloat.pi/180).translatedBy(x:517,y:-938)\n func quad(_ x:CGFloat,_ y:CGFloat,_ w:CGFloat,_ h:CGFloat)->[CGPoint] {\n  [CGPoint(x:x,y:y),CGPoint(x:x+w,y:y),CGPoint(x:x+w,y:y+h),CGPoint(x:x,y:y+h)].map {$0.applying(t)}\n }\n let host=quad(100,100,52,300),c=quad(160,140,27,42),p=quad(154,181,41,120)\n check(NativeParagraphFragmentGrouping.hasInlineBodyContinuation(candidate:c,continuation:p,host:host),"body beginning beside another column")\n check(NativeParagraphFragmentGrouping.hasInlineBodyContinuation(candidate:Array(c.reversed()),continuation:p,host:host),"reversed corners")\n check(NativeParagraphFragmentGrouping.hasInlineBodyContinuation(candidate:[c[2],c[3],c[0],c[1]],continuation:p,host:host),"cyclic corners")\n check(NativeParagraphFragmentGrouping.hasInlineBodyContinuation(candidate:p,continuation:c,host:host),"body ending continuation")\n check(!NativeParagraphFragmentGrouping.hasInlineBodyContinuation(candidate:quad(160,140,10,40),continuation:quad(159,181,10,120),host:host),"real thin ruby rail remains ruby")\n check(!NativeParagraphFragmentGrouping.hasInlineBodyContinuation(candidate:c,continuation:quad(195,181,41,120),host:host),"neighbouring column")\n check(!NativeParagraphFragmentGrouping.hasInlineBodyContinuation(candidate:c,continuation:quad(154,300,41,120),host:host),"remote same-column glyph")\n check(!NativeParagraphFragmentGrouping.hasInlineBodyContinuation(candidate:c,continuation:quad(154,100,41,200),host:host),"overlapping body is not end-to-end continuation")\n}}\nprint("PASS \\(checks) inline-body-versus-ruby checks /24angles /3scales")\n'
(cache/'main.swift').write_text(main)
subprocess.run(['swiftc','-O','-module-cache-path',str(root/'build/image-translation-host/rf-primary-module-cache'),str(translation/'NativeEngine/OCR/BrowserOCRSourceOrientation.swift'),str(translation/'NativeParagraphFragmentGrouping.swift'),str(cache/'main.swift'),'-o',str(cache/'checks')],check=True)
subprocess.run([str(cache/'checks')],check=True)
